//! R-COLOR-03 browser-decode inputs: the same 8 patch values (8×8 px blocks, one row) written as
//! PNG with different colour signalling, plus the expected sRGB decode of each tagged variant
//! (Little CMS, relative colorimetric, 8-bit). Profiles are generated by moxcms (`encode`), so no
//! third-party profile bytes are involved. Usage: decode_inputs <out-dir>

use std::fs;

use lcms2::{Intent, PixelFormat, Profile, Transform};
use moxcms::ColorProfile;
use png::chunk::ChunkType;
use serde_json::json;

pub const PATCHES: [[u8; 3]; 8] = [
    [255, 0, 0],
    [0, 255, 0],
    [0, 0, 255],
    [185, 232, 123],
    [128, 128, 128],
    [200, 100, 50],
    [0, 128, 255],
    [238, 232, 216],
];
const B: u32 = 8;

fn write_png(path: &str, chunks: &[(&[u8; 4], Vec<u8>)]) {
    let (w, h) = (B * PATCHES.len() as u32, B);
    let mut data = Vec::new();
    for _ in 0..h {
        for p in PATCHES {
            for _ in 0..B {
                data.extend_from_slice(&p);
            }
        }
    }
    let mut e = png::Encoder::new(fs::File::create(path).unwrap(), w, h);
    e.set_color(png::ColorType::Rgb);
    e.set_depth(png::BitDepth::Eight);
    let mut wr = e.write_header().unwrap();
    for (t, d) in chunks {
        wr.write_chunk(ChunkType(**t), d).unwrap();
    }
    wr.write_image_data(&data).unwrap();
}

fn iccp(icc: &[u8]) -> Vec<u8> {
    let mut v = b"vectra-test\0\0".to_vec(); // name, NUL, compression method 0
    v.extend(miniz_oxide::deflate::compress_to_vec_zlib(icc, 9));
    v
}

fn expected(icc: &[u8]) -> Vec<[u8; 3]> {
    let src = Profile::new_icc(icc).unwrap();
    let t: Transform<[u8; 3], [u8; 3]> = Transform::new(
        &src,
        PixelFormat::RGB_8,
        &Profile::new_srgb(),
        PixelFormat::RGB_8,
        Intent::RelativeColorimetric,
    )
    .unwrap();
    let mut out = vec![[0u8; 3]; PATCHES.len()];
    t.transform_pixels(&PATCHES, &mut out);
    out
}

fn main() {
    let out = std::env::args().nth(1).expect("usage: decode_inputs <out-dir>");
    fs::create_dir_all(&out).unwrap();
    let p3 = ColorProfile::new_display_p3().encode().unwrap();
    let adobe = ColorProfile::new_adobe_rgb().encode().unwrap();
    fs::write(format!("{out}/gen-display-p3.icc"), &p3).unwrap();
    write_png(&format!("{out}/untagged.png"), &[]);
    write_png(&format!("{out}/srgb-chunk.png"), &[(b"sRGB", vec![0])]);
    write_png(&format!("{out}/iccp-display-p3.png"), &[(b"iCCP", iccp(&p3))]);
    write_png(&format!("{out}/iccp-adobe-rgb.png"), &[(b"iCCP", iccp(&adobe))]);
    // cICP: primaries 12 (P3-D65), transfer 13 (sRGB), matrix 0, full range.
    write_png(&format!("{out}/cicp-display-p3.png"), &[(b"cICP", vec![12, 13, 0, 1])]);
    // gAMA 1.0 (linear-encoded data): 100000 / 100000.
    write_png(
        &format!("{out}/gama-linear.png"),
        &[(b"gAMA", 100_000u32.to_be_bytes().to_vec())],
    );
    let hex = |v: &[[u8; 3]]| {
        v.iter()
            .map(|c| format!("#{:02x}{:02x}{:02x}", c[0], c[1], c[2]))
            .collect::<Vec<_>>()
    };
    let report = json!({
        "block": B,
        "patches": hex(&PATCHES),
        "expectedSrgbIfConverted": {
            "untagged": hex(&PATCHES), "srgb-chunk": hex(&PATCHES),
            "iccp-display-p3": hex(&expected(&p3)), "cicp-display-p3": hex(&expected(&p3)),
            "iccp-adobe-rgb": hex(&expected(&adobe)),
        },
        "profiles": { "display-p3-bytes": p3.len(), "adobe-rgb-bytes": adobe.len() },
    });
    fs::write(
        format!("{out}/expected.json"),
        serde_json::to_string_pretty(&report).unwrap() + "\n",
    )
    .unwrap();
}
